assert_eq!(
        rendered,
        format!(
            "+---+
| A |
+---+

+---+
| B |
+---+

+---+
| C |
+---+

relations:
{ab}
{ba}
{ac}
{ca}
{bc}
{cb}
"
        )
    )

assert_eq!(
        error,
        AsciiError::InvalidOption {
            field: "layout_profile",
            message: "is not admitted for this diagram family",
        }
    )

assert!(matches!(
            error,
            AsciiError::UnsupportedFeature {
                diagram_type: "sequence",
                feature: "actor lifecycle actors",
            }
        ))

assert!(matches!(
        err,
        merman_ascii::AsciiError::UnsupportedFeature {
            diagram_type: "flowchart",
            feature: "unsupported flowchart node shape projections",
        }
    ))

assert_eq!(
                    chars[head],
                    if direction == "RL" {
                        right_head
                    } else {
                        left_head
                    },
                    "{rendered}"
                )

assert!(
        rendered.contains(
            r#"interfaceRef(id(bytes=10)="interface0" label(bytes=8)="IService" target(bytes=7)="Service" ordinal=1"#
        ),
        "{rendered}"
    )

assert_eq!(
        strip_html_spans(&rendered),
        format!(
            "+---+
| A |
+---+

+---+
| B |
+---+

+---+
| C |
+---+

relations:
{html_ab}
{html_ba}
{html_ac}
{html_ca}
{html_bc}
{html_cb}
"
        )
    )

assert!(matches!(
        error,
        AsciiError::WidthOverflow { max_width: 60, actual_width, .. }
            if actual_width == selected.primary_extent.width
    ))

assert_eq!(
                error,
                AsciiError::UnsupportedFeature {
                    diagram_type: "class",
                    feature: "interfaces with missing target classes",
                },
                "interface declaration order must not change validation"
            )

assert_eq!(
                            allow.outcome,
                            if overflowed {
                                AsciiOutputOutcome::WideAllowed
                            } else {
                                AsciiOutputOutcome::Primary
                            }
                        )

assert!(
                                matches!(
                                    error_result,
                                    Err(AsciiError::WidthOverflow {
                                        max_width: actual_max,
                                        actual_width,
                                        ..
                                    }) if actual_max == max_width
                                        && actual_width == baseline.primary_extent.width
                                ),
                                "Error {fixture}/{options:?}/width={max_width} produced {error_result:?}"
                            )

assert_eq!(
                        error,
                        AsciiError::InvalidOption {
                            field: "ascii_viewport.overflow",
                            message: "fallback is not admitted for the selected output encoding",
                        }
                    )

assert_eq!(
        error,
        AsciiError::InvalidOption {
            field: "ascii_viewport.overflow",
            message: "fallback is not admitted for the selected output encoding",
        }
    )

assert_eq!(
                output.outcome,
                if width < 120 {
                    AsciiOutputOutcome::WideAllowed
                } else {
                    AsciiOutputOutcome::Primary
                }
            )

assert!(
            copied
                .chars()
                .zip(expected.chars())
                .all(|(original, corrected)| {
                    original == corrected || (matches!(original, '-' | '|') && corrected == '+')
                }),
            "{} must only preserve the frame directions at route crossings",
            fixture.key()
        )

assert!(matches!(
            error,
            AsciiError::UnsupportedFeature {
                diagram_type: "class",
                feature: "inconsistent class namespace ownership",
            }
        ))

assert!(
            err.contains(&format!(
                "No such shape: {shape}. Shape names should be lowercase."
            )),
            "internal layout shape should be rejected before ASCII rendering:\n{err}"
        )

assert not used_box_chars, (
            f"ASCII mode output contains unicode chars: {used_box_chars}"
        )

assert arrow_count >= 4, (
            f"Expected 4 arrows for 4 edges, found {arrow_count}:\n{out}"
        )

assert not used_box_chars, (
            f"ASCII mode output for {name} contains unicode chars: {used_box_chars}"
        )
